var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('parses strings up to 10000 chars', function () {
    var long = '1' + new Array(10000).join('0');
    assert.strictEqual(ms(long + ' days'), Number.MAX_SAFE_INTEGER);
  });

  it('returns undefined for strings longer than 100 chars', function () {
    var str = '1 day day day day day day day day day day day day day day day day';
    assert.strictEqual(str.length > 100, true);
    assert.strictEqual(ms(str), undefined);
  });
});

